import json,re,sys,tempfile
from pathlib import Path
from playwright.sync_api import sync_playwright
mode=sys.argv[1] if len(sys.argv)>1 else 'local';out=Path(sys.argv[2]) if len(sys.argv)>2 else Path(tempfile.mkdtemp(prefix='ror-history-controls-'));out.mkdir(parents=True,exist_ok=True)
url='https://grahamror.github.io/ror-dashboard/' if mode=='live' else 'http://127.0.0.1:8780/'
with sync_playwright() as p:
 b=p.chromium.launch(headless=True);page=b.new_page(viewport={'width':1440,'height':1000},locale='en-GB',timezone_id='Europe/London');page.clock.set_fixed_time('2026-11-09T20:00:00Z');errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(url,wait_until='networkidle')
 fy=page.get_by_label('Shopify financial year',exact=True);fy.wait_for();page.wait_for_function("Array.from(document.querySelector('[aria-label=\"Shopify financial year\"]').options).some(o=>o.value==='FY16')")
 years=fy.locator('option').evaluate_all('(a)=>a.map(x=>x.value)');assert 'FY16' in years and 'FY27' in years and 'FY15' not in years
 native_before=page.locator('body').inner_text();fy.select_option('FY16');report=page.locator('[data-history-report="Shopify"]');table=report.get_by_role('table');assert table.locator('tbody tr').count()==12
 assert '£391.00' in report.locator('[data-history-month="2016-01"]').inner_text();assert table.inner_text().count('Workbook · recorded revenue')==7
 assert '01-08-2015 → 31-07-2016' in report.inner_text();assert 'Financial coverage incomplete' not in page.locator('body').inner_text()
 page.screenshot(path=str(out/'shopify-fy16-desktop.png'),full_page=True,animations='disabled');fy.select_option('FY24');assert table.locator('tbody tr').count()==12;assert table.inner_text().count('Workbook · recorded revenue')==5;assert table.inner_text().count('Native feed · Net Sales')==7
 fy.select_option('FY27');assert not report.count();assert page.locator('body').inner_text()==native_before
 for name in ['Overview','Yesterday','Monthly','Products','Email','Ads','Margin']:page.get_by_text(name,exact=True).first.click()
 page.set_viewport_size({'width':390,'height':844});fy.select_option('FY16');assert page.evaluate('document.documentElement.scrollWidth<=innerWidth+1');page.screenshot(path=str(out/'shopify-fy16-mobile.png'),full_page=True,animations='disabled');page.set_viewport_size({'width':1440,'height':1000})
 page.get_by_text('ROR Sales',exact=True).click();dates=page.get_by_label('Page date range',exact=True);dates.wait_for();page.wait_for_function("Array.from(document.querySelector('[aria-label=\"Page date range\"]').options).some(o=>o.value==='FY16')")
 assert 'FY15' in dates.locator('option').evaluate_all('(a)=>a.map(x=>x.value)');dates.select_option('FY16');r=page.locator('[data-history-report="Page"]');assert r.get_by_role('table').locator('tbody tr').count()==12;assert '£391.00' in r.locator('[data-history-month="2016-01"]').inner_text();assert not page.locator('[data-ror-metric="revenue"]').count();assert not page.locator('[data-ror-section="history"]').count()
 page.screenshot(path=str(out/'ror-fy16-desktop.png'),full_page=True,animations='disabled');page.get_by_label('Page store',exact=True).select_option('etsy');assert r.get_by_role('columnheader').all_text_contents()==['Month','Etsy Net Sales']
 page.set_viewport_size({'width':390,'height':844});assert page.evaluate('document.documentElement.scrollWidth<=innerWidth+1');page.screenshot(path=str(out/'ror-fy16-mobile.png'),full_page=True,animations='disabled');page.set_viewport_size({'width':1440,'height':1000});page.get_by_label('Page store',exact=True).select_option('all');dates.select_option('currentFY');page.wait_for_function("document.querySelector('[data-ror-metric=\"revenue\"]')?.innerText.includes('£79,554.92')")
 page.get_by_label('Sales comparison date range',exact=True).select_option('FY16');comp=page.locator('[data-history-report="Sales comparison"]');assert comp.get_by_role('table').locator('tbody tr').count()==12;assert '£79,554.92' in page.locator('[data-ror-metric="revenue"]').inner_text()
 page.get_by_label('Sales explorer date range',exact=True).select_option('FY16');expl=page.locator('[data-history-report="Sales explorer"]');assert expl.get_by_role('table').locator('tbody tr').count()==12;page.get_by_label('Sales explorer store',exact=True).select_option('noths');assert expl.get_by_role('columnheader').all_text_contents()==['Month','NOTHS Net Sales']
 dates.select_option('custom');page.get_by_label('Page start date',exact=True).fill('2016-01-15');page.get_by_label('Page end date',exact=True).fill('2016-02-10');r=page.locator('[data-history-report="Page"]');assert r.get_by_role('table').locator('tbody tr').count()==2
 for row in r.get_by_role('table').locator('tbody tr').all():assert row.locator('td').nth(1).inner_text().startswith('—');assert 'full months only' in row.locator('td').nth(1).inner_text()
 assert '15-01-2016 → 10-02-2016' in r.inner_text();assert not re.search(r'\b\d{4}-\d{2}-\d{2}\b',page.locator('body').inner_text());assert not errors,errors
 # Missing or corrupt history leaves original current-year reporting available and retry restores the normal year controls.
 page.route('**/finance/marketplaces/historical/snapshots/*.json*',lambda route:route.fulfill(body='{}',content_type='application/json'))
 page.reload(wait_until='networkidle');page.get_by_text('ROR Sales',exact=True).click();page.get_by_label('Page date range',exact=True).select_option('currentFY');page.wait_for_function("document.querySelector('[data-ror-metric=\"revenue\"]')?.innerText.includes('£79,554.92')");page.get_by_label('Retry earlier sales years',exact=True).wait_for();page.unroute('**/finance/marketplaces/historical/snapshots/*.json*');page.get_by_label('Retry earlier sales years',exact=True).click();page.wait_for_function("Array.from(document.querySelector('[aria-label=\"Page date range\"]').options).some(o=>o.value==='FY16')")
 assert '£79,554.92' in page.locator('[data-ror-metric="revenue"]').inner_text();assert not errors,errors
 # Use an independent page per missing module to isolate each failure from earlier route/cache state.
 for script in ['dashboard2/historical-sales.js','finance/historical/reporting.js','finance/historical/loader.js']:
  fault=b.new_page(locale='en-GB',timezone_id='Europe/London');fault.clock.set_fixed_time('2026-11-09T20:00:00Z');fault_errors=[];fault.on('pageerror',lambda e:fault_errors.append(str(e)));fault.route('**/'+script+'*',lambda route:route.abort());fault.goto(url,wait_until='networkidle');fault.get_by_text('ROR Sales',exact=True).click();fault.get_by_label('Page date range',exact=True).select_option('currentFY');fault.wait_for_function("document.querySelector('[data-ror-metric=\"revenue\"]')?.innerText.includes('£79,554.92')");fault.get_by_label('Retry earlier sales years',exact=True).wait_for();assert not fault_errors,fault_errors;fault.close()
 result={'mode':mode,'shopifyYearOptions':years,'shopifyFY16MonthlyRows':12,'shopifyFY16WorkbookMonths':7,'shopifyFY24WorkbookMonths':5,'shopifyFY24NativeMonths':7,'nativeGrowthRestoredExactly':True,'rorMainFY16Direct':True,'independentComparisonAndExplorerFY16':True,'storeFiltersRespected':True,'partialWorkbookMonthsWithheld':True,'requestedDatesPreserved':True,'currentFYNet':79554.92,'growthTabs':7,'mobileOverflow':False,'yearFirstDates':False,'corruptArchiveIsolated':True,'retryRestoresYearOptions':True,'missingHistoryScriptsIsolated':3,'pageErrors':errors}
 (out/'results.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result));b.close()
